def split_csv(line):
    """
    Parse one line of CSV and return its fields as a list of strings.
    Returns None if the line is malformed.
    """
    fields = []
    i = 0

    while i <= len(line):
        # Start of a new field
        if i == len(line):
            # End of line - if we haven't started reading anything yet, we have one empty field
            if not fields:
                fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what comes next: must be comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        # Move past the comma if present
                        if i < len(line):
                            i += 1
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote - malformed
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                # Unquoted fields must not contain double quotes
                if line[i] == '"':
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            # Move past the comma if present
            if i < len(line):
                i += 1

    return fields

